CREATE SEQUENCE IF NOT EXISTS chamado_numero_seq START WITH 1 INCREMENT BY 1;
CREATE TABLE IF NOT EXISTS shedlock (name VARCHAR(64) PRIMARY KEY, lock_until TIMESTAMP NOT NULL, locked_at TIMESTAMP NOT NULL, locked_by VARCHAR(255) NOT NULL);
CREATE TABLE IF NOT EXISTS sla_politicas (prioridade VARCHAR(10) PRIMARY KEY, horas_primeira_resposta INTEGER NOT NULL, horas_resolucao INTEGER NOT NULL, atualizado_em TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
MERGE INTO sla_politicas (prioridade, horas_primeira_resposta, horas_resolucao) KEY(prioridade) VALUES ('CRITICA', 1, 4), ('ALTA', 2, 8), ('MEDIA', 4, 24), ('BAIXA', 8, 40);
CREATE TABLE IF NOT EXISTS expediente (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, dia_semana SMALLINT NOT NULL, inicio TIME NOT NULL, fim TIME NOT NULL, ativo BOOLEAN NOT NULL);
MERGE INTO expediente KEY(id) VALUES (1, 1, '09:00', '18:00', TRUE), (2, 2, '09:00', '18:00', TRUE), (3, 3, '09:00', '18:00', TRUE), (4, 4, '09:00', '18:00', TRUE), (5, 5, '09:00', '18:00', TRUE);
CREATE TABLE IF NOT EXISTS feriados (id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, data DATE NOT NULL UNIQUE, descricao VARCHAR(180) NOT NULL);
